#x-insuit-tab {
    display: flex;
    align-items: center!important;
    top: 150px;
    left: 0!important;
    border: 0;
    line-height: 18px;
    position: fixed;
    margin: 0;
    padding: 5px 1px 5px 5px;
    outline: 0;
    font-family: InsuitABeeZee, Arial, Helvetica, Verdana, sans-serif;
    font-weight: inherit;
    font-style: inherit;
    vertical-align: baseline;
    background: none 0 0 repeat scroll rgba(0, 105, 190, .9);
    z-index: 2147483646;
    border-radius: 0 20px 20px 0;
    visibility: visible;
    max-height: 200px
}

#x-insuit-tab.focused {
    box-shadow: 0 0 0 5px #af0421
}

#x-insuit-tab.insuit-tab-right {
    left: unset!important;
    right: 0;
    border-radius: 20px 0 0 20px;
    flex-direction: row-reverse
}

#x-insuit-tab.insuit-tab-right.closed #x-insuit-tab-arrow>img {
    transform: scaleX(1)
}

#x-insuit-tab.insuit-tab-right.open #x-insuit-tab-arrow>img {
    transform: scaleX(-1)
}

#x-insuit-tab-container>span>div {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center
}

#x-insuit-tab-container>span>div>span {
    white-space: nowrap
}

#x-insuit-tab-title {
    cursor: pointer;
    writing-mode: vertical-rl;
    transform: rotate(180deg);
    height: min-content;
    height: min-intrinsic;
    text-align: center;
    padding: 0;
    border: 0;
    outline: 0;
    font-size: 16px;
    font-stretch: condensed;
    vertical-align: baseline;
    color: #fff;
    text-decoration: none
}

#x-insuit-tab-title:focus {
    box-shadow: 0 0 0 3px #af0421
}

#x-tab-custom-image,
#x-tab-insuit-image:before {
    margin: 10px;
    width: 32px;
    height: auto
}

#x-tab-insuit-image {
    transform: rotate(270deg)
}

#x-insuit-tab a.focused {
    border-bottom: 2px solid #af0421
}

#x-insuit-tab.closed #x-insuit-tab-container {
    width: 0
}

#x-insuit-tab.open #x-insuit-tab-container {
    width: 45px
}

#x-insuit-tab-container {
    position: relative;
    color: #fff;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 5px;
    transition-property: width;
    transition-duration: .7s;
    padding: 2px
}

#x-insuit-tab.closed #x-insuit-tab-container>* {
    visibility: hidden
}

#x-insuit-tab.closed #x-insuit-tab-arrow {
    transform: scaleX(-1)
}

#x-insuit-tab.open #x-insuit-tab-arrow {
    transform: scaleX(1)
}

#x-insuit-tab.open #x-insuit-tab-arrow:before {
    margin-left: -2px
}

#x-insuit-tab-arrow {
    width: 10px;
    min-height: 100px;
    display: flex;
    justify-content: start;
    align-items: center;
    position: relative;
    text-align: center;
    color: #fff;
    cursor: pointer;
    height: 12px;
    transition-property: transform;
    transition-duration: .6s
}

#x-insuit-tab #x-insuit-tab-arrow:before {
    font-family: insuit-icons;
    font-style: normal;
    font-weight: 400;
    speak: none;
    display: inline-block;
    text-decoration: inherit;
    width: 1em;
    margin-right: .2em;
    text-align: center;
    font-variant: normal;
    text-transform: none;
    line-height: 1em;
    margin-left: .2em;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    content: '\e800'!important;
    color: #fff;
    font-size: 12px
}

@media print {
    #x-insuit-tab {
        display: none
    }
}

#insuit-jump-main {
    background: rgba(0, 105, 190, .9);
    color: #fff;
    text-decoration: none;
    left: 40%;
    top: 0;
    padding: 8px;
    position: absolute;
    transform: translateY(-100%);
    opacity: 0;
    transition: transform .3s
}

#insuit-jump-main:focus {
    opacity: 1!important;
    transform: translateY(0)!important;
    z-index: 10000;
    transform: translateY(0)!important
}
